-- ============================================================================
-- D3: Electrofacies joins the catalogue, the THIRD course of the Data & AI
-- module.
--
-- Catalogue row (module 'data_ai'; path_order 68, directly above D2
-- mlcore at 67; prereq_slug NULL, as D1 and D2 carry it: whether D3 requires
-- D2 is a go-live decision; school left at its default) plus the three
-- capstones and their eighteen graded fields, generated by
-- tools/course-waves/facies/gen_course.py from the ENGINE'S OWN RUN
-- (d3_capstone.mjs through the vendored engines/dataai/cluster.js and ml.js),
-- which it refuses to write unless fields.json carries exactly that run's
-- values and the tolerance gradedTolerance.js derives. Deep seeds are three
-- separate migrations; the go-live is a fifth and is HELD until a NextGen
-- production upload carries the route /dashboard/apps/facies, because the 78
-- lessons, the teaching lab (faciesLab.js), its three explorer panels and the
-- capstone case files ship in the zip and not in this database.
--
-- THE ONE SENTENCE THE COURSE IS. An electrofacies is a group of depth samples
-- whose logs look alike, and it is worth something only when it is checked
-- against the rock, so the course teaches grouping logs into electrofacies
-- (Associate), judging the groups against core (Professional), and predicting
-- facies with the engine's own rules (Expert), and grades each tier on its own
-- question with numbers the engine returns.
--
-- THE ENGINE. engines/dataai/cluster.js, vendored sha-identical with
-- petrolord-engines ef4058f (engines #253 and #254), with the scalers and
-- classificationReport of ml.js. Scaling for clustering is fitted on the rows
-- passed with the population standard deviation; PCA on the correlation
-- matrix uses the sample standard deviation and a stated sign rule; k-means
-- seeds with k-means++ on one mulberry32 stream and keeps the lowest inertia
-- of its starts; distance and merge ties are judged in a 1e-12 relative band.
--
-- WHAT IS GRADED. IHIALA (Associate) grades a scaler's scale, the first
-- component's share, a loading and a score, a k-means inertia and a centre in
-- log units; NKWELLE (Professional) grades an elbow drop fraction, a Ward
-- silhouette and merge height, an adjusted Rand index, a one-to-one macro F1
-- and a majority accuracy; OGBUNIKE (Expert) grades a held-out kNN accuracy, a
-- nearest distance, the Gini of the node a tied root sends right, an
-- importance, a held-out tree accuracy and a range check on an uncored well.
-- Every value is a return value of the engine, and the data it was run on is
-- in the case file the prompt names.
--
-- All eighteen graded values were swept against every number the digest
-- prints and against every number handed to a learner in a prompt, a label or
-- a case file, at each field's own shipped tolerance: 0 collisions, and 0
-- pairwise. No prompt states another tier's graded value.
-- ============================================================================

insert into public.academy_apps (slug, name, module, path_order, status, prereq_slug)
values ('facies', 'Electrofacies', 'data_ai', 68, 'coming_soon', null)
on conflict (slug) do nothing;

insert into public.academy_capstones
    (app_slug, tier, cert_tier, dataset, title, prompt, fields)
values
(
  'facies', 'beginner', 'associate',
  'IHIALA, 6 cored wells, 150 rows',
  'Grouping logs into electrofacies',
  'IHIALA, a field of 6 cored wells, IHIALA-1 to IHIALA-6, each logged at a one foot step. One case file comes with this capstone. ihiala_wells.csv carries 150 rows, 25 a well, in well order and in depth order within each well: the well name, the depth in ft, GR in gAPI, RHOB in g/cm3, NPHI in v/v, PEF in b/e, CALI in in, and the core FACIES. Use the four logs GR, RHOB, NPHI and PEF on all 150 rows, rows counted from 0 in the order of the file, so row 24 is the last row of IHIALA-1. Report six values: the scale of GR that standard scaling fits on those rows, the population standard deviation (n), in gAPI; the explained variance ratio of the first principal component of the correlation matrix; the loading of NPHI on that component, with the engine''s sign convention; the score of row 0 on that component; the inertia, in squared standard units, of k-means with k 4, seed 7 and 10 starts, standard scaling; and the GR, in gAPI, of the centre of the cluster row 24 sits in under that clustering. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','ihiala_gr_scale_gapi', 'label','The scale of GR, the population standard deviation (n)', 'unit','gAPI', 'expected',30.964884168289004, 'tol',5e-07),
    jsonb_build_object('key','ihiala_pc1_ratio', 'label','The explained variance ratio of the first principal component, correlation matrix', 'unit','dimensionless', 'expected',0.5691754468344539, 'tol',5e-07),
    jsonb_build_object('key','ihiala_pc1_nphi_loading', 'label','The loading of NPHI on the first principal component', 'unit','dimensionless', 'expected',-0.7646436270213334, 'tol',5e-07),
    jsonb_build_object('key','ihiala_pc1_score_first_row', 'label','The score of row 0 on the first principal component', 'unit','dimensionless', 'expected',-0.5709520560870318, 'tol',5e-07),
    jsonb_build_object('key','ihiala_kmeans_inertia', 'label','The inertia of k-means at k 4, seed 7', 'unit','standard units squared', 'expected',47.80610578301488, 'tol',5e-07),
    jsonb_build_object('key','ihiala_row24_cluster_gr_centre_gapi', 'label','The GR of the centre of the cluster row 24 sits in', 'unit','gAPI', 'expected',41.956626506024094, 'tol',5e-07)
  )
),
(
  'facies', 'intermediate', 'professional',
  'NKWELLE, 7 cored wells, 168 rows',
  'Judging groups against core',
  'NKWELLE, a field of 7 cored wells, NKWELLE-1 to NKWELLE-7, each logged at a one foot step. One case file comes with this capstone. nkwelle_wells.csv carries 168 rows, 24 a well, in well order and in depth order within each well: the well name, the depth in ft, GR in gAPI, RHOB in g/cm3, NPHI in v/v, PEF in b/e, CALI in in, and the core FACIES. Use the four logs GR, RHOB, NPHI and PEF on all 168 rows, with standard scaling throughout. Report six values. First, the drop fraction at k 4 of the elbow over k 1 to 8 with seed 5 and 10 starts. Second, the mean silhouette of the Ward linkage cut at k 4, scored on the standardised logs. Third, the height, in standard units, of the next merge above that Ward cut, the first merge the cut undoes. Fourth, the adjusted Rand index of the complete linkage cut at k 4 against the core facies. Fifth, the macro F1 of one-to-one matching of k-means at k 4, seed 5 and 10 starts, against the core facies. Sixth, the accuracy of majority matching of k-means at k 6, seed 5 and 10 starts, against the core facies. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','nkwelle_elbow_drop_fraction_k4', 'label','The drop fraction of the elbow at k 4', 'unit','dimensionless', 'expected',0.29491071673313907, 'tol',5e-07),
    jsonb_build_object('key','nkwelle_ward_silhouette', 'label','The mean silhouette of the Ward cut at k 4', 'unit','dimensionless', 'expected',0.5894448481870038, 'tol',5e-07),
    jsonb_build_object('key','nkwelle_ward_height_above_cut', 'label','The height of the next Ward merge above the cut at k 4', 'unit','standard units', 'expected',6.101223754624051, 'tol',5e-07),
    jsonb_build_object('key','nkwelle_complete_ari', 'label','The adjusted Rand index of the complete-linkage cut at k 4 against the core facies', 'unit','dimensionless', 'expected',0.9716598290573624, 'tol',5e-07),
    jsonb_build_object('key','nkwelle_one_to_one_macro_f1', 'label','The macro F1 of one-to-one matching of k-means at k 4', 'unit','dimensionless', 'expected',0.9797123780174628, 'tol',5e-07),
    jsonb_build_object('key','nkwelle_majority_accuracy_k6', 'label','The accuracy of majority matching of k-means at k 6', 'unit','dimensionless', 'expected',0.9761904761904762, 'tol',5e-07)
  )
),
(
  'facies', 'advanced', 'expert',
  'OGBUNIKE, 7 wells, one of them uncored',
  'Predicting facies and the engine''s own rules',
  'OGBUNIKE, a field of 7 wells, OGBUNIKE-1 to OGBUNIKE-7, each logged at a one foot step. One case file comes with this capstone. ogbunike_wells.csv carries 175 rows, 25 a well, in well order and in depth order within each well: the well name, the depth in ft, GR in gAPI, RHOB in g/cm3, NPHI in v/v, PEF in b/e, CALI in in, and the core FACIES. OGBUNIKE-7 was not cored, and its FACIES is written null on every row; it was logged with a gamma ray tool that reads 26 gAPI high on every row. The other 6 wells are cored, 150 rows. Report six values. First, the accuracy on OGBUNIKE-4 of kNN with k 5 on the four logs GR, RHOB, NPHI and PEF, standard scaling fitted on the training rows, trained on the other 5 cored wells, OGBUNIKE-1, OGBUNIKE-2, OGBUNIKE-3, OGBUNIKE-5, OGBUNIKE-6. Second, the distance, in standard units, from row 0 of OGBUNIKE-4, its shallowest row, rows counted from 0 within the well, to its nearest training row in that run. Third, the Gini impurity of node 2, the node the root sends right, of the classification tree grown on all 150 cored rows at the default maxDepth 5, with the five channels in the column order GR, RHOB, NPHI, PEF, CALI. Fourth, the importance of NPHI in that tree. Fifth, the accuracy on OGBUNIKE-4 of a tree of maxDepth 3 grown on the other 5 cored wells with the same five channels in the same order. Sixth, the highest GR of OGBUNIKE-7 after min-max scaling fitted on the four logs of the 150 cored rows. All six to six decimals.',
  jsonb_build_array(
    jsonb_build_object('key','ogbunike_knn_heldout_accuracy', 'label','The kNN accuracy on OGBUNIKE-4', 'unit','dimensionless', 'expected',0.76, 'tol',5e-07),
    jsonb_build_object('key','ogbunike_knn_nearest_distance', 'label','The distance from row 0 of OGBUNIKE-4 to its nearest training row', 'unit','standard units', 'expected',0.2483094734611528, 'tol',5e-07),
    jsonb_build_object('key','ogbunike_cart_node2_gini', 'label','The Gini impurity of node 2', 'unit','dimensionless', 'expected',0.6649365628604382, 'tol',5e-07),
    jsonb_build_object('key','ogbunike_cart_nphi_importance', 'label','The importance of NPHI in the tree', 'unit','dimensionless', 'expected',0.40300385114933807, 'tol',5e-07),
    jsonb_build_object('key','ogbunike_cart_depth3_heldout_accuracy', 'label','The accuracy on OGBUNIKE-4 of the tree of maxDepth 3', 'unit','dimensionless', 'expected',0.64, 'tol',5e-07),
    jsonb_build_object('key','ogbunike_uncored_gr_minmax_max', 'label','The highest GR of OGBUNIKE-7, min-max scaled on the cored rows', 'unit','dimensionless', 'expected',1.222314049586777, 'tol',5e-07)
  )
)
on conflict (app_slug, tier) do nothing;
